# PuzzleSolver installer.
#
# Per-user on purpose (DESIGN 11): everything lands under %LOCALAPPDATA% and %APPDATA%
# so no administrator prompt appears, and nothing is written to Program Files or HKLM.
#
# This script is the platform half. The launcher text and the Startup-folder shim are
# generated by app\src\deploy\install.js, which is where the tests live; this file only
# locates paths and launches it.
#
# Executed on windows-latest since #59. What remains unverified is the *unprivileged*
# path, because the runner is an administrator (issue #163).

param(
    # Unattended or scripted installs: install only, do not start the app (and therefore
    # do not open the first-run setup page). All other runs start the app themselves.
    [switch]$NoStart,

    # Clear the Mark-of-the-Web from the payload before installing. Off by default: the
    # mark is an accurate record of where the file came from, and removing it is the
    # user's decision, not the installer's (#176).
    [switch]$Unblock
)

$ErrorActionPreference = 'Stop'

$InstallDir = Join-Path $env:LOCALAPPDATA 'Programs\PuzzleSolver'
Write-Host "Installing PuzzleSolver to $InstallDir"

# If the payload is already the install dir (a re-run), skip the self-copy.
$Source = [IO.Path]::GetFullPath($PSScriptRoot)
$Here = [IO.Path]::GetFullPath($InstallDir)

# Mark-of-the-Web (#176). Zone.Identifier is the alternate data stream Explorer puts on
# every file it extracts from a downloaded ZIP - the "this came from the internet" mark.
# It is an accurate signal about the download, so the installer reports it and never
# clears it silently: `-Unblock` is how the user asks for that. Detection runs before the
# copy for a reason - clearing the source first is what keeps the installed files clean.
#
# The report names the files and the one command that fixes them, because the wrong
# instruction is the common one: unblocking the ZIP *before* extracting is what prevents
# the flags (Explorer copies the ZIP's mark onto each extracted file); unblocking the
# extracted files afterwards works but is a different command (#176).
function Get-MarkedFile([string]$Dir) {
    if (-not (Test-Path -LiteralPath $Dir)) { return @() }
    return @(
        Get-ChildItem -LiteralPath $Dir -Recurse -File -ErrorAction SilentlyContinue |
            Where-Object { Get-Item -LiteralPath $_.FullName -Stream Zone.Identifier -ErrorAction SilentlyContinue } |
            ForEach-Object { $_.FullName }
    )
}

$Marked = @(Get-MarkedFile $Source)
if ($Source -ne $Here) { $Marked += @(Get-MarkedFile $Here) }
$Marked = @($Marked | Sort-Object -Unique)

if ($Marked.Count -gt 0) {
    if ($Unblock) {
        foreach ($file in $Marked) { Unblock-File -LiteralPath $file }
        $Remaining = @(Get-MarkedFile $Source)
        if ($Source -ne $Here) { $Remaining += @(Get-MarkedFile $Here) }
        $Remaining = @($Remaining | Sort-Object -Unique)
        Write-Host "Mark-of-the-Web: cleared the download mark from $($Marked.Count) file(s) (-Unblock); $($Remaining.Count) file(s) are still marked."
    } else {
        Write-Host "Mark-of-the-Web: $($Marked.Count) file(s) in this download carry the internet-download mark, so Windows warns the first time each is opened:"
        foreach ($file in $Marked) { Write-Host "  $file" }
        Write-Host 'No file was changed. To clear the mark, unblock the ZIP before extracting (Unblock-File .\PuzzleSolver-<version>-win-x64.zip); clearing these extracted files in place works too, with "Get-ChildItem . -Recurse -File | Unblock-File". This installer will clear them if re-run with -Unblock.'
    }
}

if ($Source -ne $Here) {
    New-Item -ItemType Directory -Force -Path $InstallDir | Out-Null
    Copy-Item -Recurse -Force (Join-Path $PSScriptRoot '*') $InstallDir
}

$Node = Join-Path $InstallDir 'node.exe'
$Deploy = Join-Path $InstallDir 'app\src\deploy\install.js'
if (-not (Test-Path $Node)) { throw "node.exe is missing from $InstallDir" }
if (-not (Test-Path $Deploy)) { throw "app is missing from $InstallDir" }

# Writes PuzzleSolver.vbs, the per-user Startup-folder shim, and the commented example
# config beside where config.toml lives (#181). A user's edited example is kept.
#
# `$ErrorActionPreference = 'Stop'` does not cover a native child's exit code - a
# non-zero exit from node.exe is not a PowerShell error - so it must be checked
# explicitly, or this script prints "Installed" after a failure (#162). The pattern is
# the same one run-smoke.ps1 and run-deploy.ps1 already use.
& $Node $Deploy
if ($LASTEXITCODE -ne 0) {
    throw "PuzzleSolver install failed: node.exe exited with $LASTEXITCODE. Files are in $InstallDir; run PuzzleSolver.vbs to start the app, but it will not start at logon."
}

# Start the app now, so install is one step. Two details matter:
#
#  - It starts PuzzleSolver.vbs, not the per-user Startup shim. The shim sleeps 20 s
#    before delegating (the logon delay); going through it would make the installer
#    appear to hang and then start long after it said it had.
#  - It is detached: Start-Process returns as soon as wscript.exe is created, so the
#    installer exits and the app keeps running. The launcher runs node with a hidden
#    window, so no console flashes.
#
# The `-NoStart` switch is the escape hatch for a scripted install (a package manager,
# an image build, a machine with no interactive desktop), where opening the first-run
# setup page in a browser is wrong. It is off by default because install-and-go is the
# ordinary user path: on a fresh install the app opens its setup page and asks for the
# Pushbullet token (#56).
if ($NoStart) {
    Write-Host "Installed to $InstallDir. It starts at logon; the app was not started now (-NoStart)."
} else {
    $Launcher = Join-Path $InstallDir 'PuzzleSolver.vbs'
    $Wscript = Join-Path $env:SystemRoot 'System32\wscript.exe'
    if (-not (Test-Path $Wscript)) { $Wscript = 'wscript.exe' }
    # Quote the launcher: %LOCALAPPDATA% can contain a space (e.g. a username with one).
    Start-Process -FilePath $Wscript -ArgumentList "`"$Launcher`""
    Write-Host "Installed to $InstallDir. It starts at logon, and it is starting now."
}
